// Official one-person reflection themes. Keep this registry separate from the
// regular 40-card group catalog: solo cards are fixed-order and solo-only.
// Deck ids and card ids (<deckId>-01..-12) are kept stable: the 11 earlier themes had their
// title/subtitle/description/questions replaced in place, so saved notes, my-sets, shared sets
// and in-progress sessions still resolve. NEVER delete a deck/card id; to retire a theme in the
// future, set hidden: true on it instead (and keep it in catalog lookups).
// `care` is an optional UI hint: 'distress' (show the fixed support line) | 'love' (show the
// relationship-safety line) | undefined. It is a fixed per-theme flag; no text analysis is done.
const makeQuestions = (deckId, texts) => texts.map((text, index) => ({
  id: `${deckId}-${String(index + 1).padStart(2, '0')}`,
  text,
  order: index + 1,
  r18: false,
}));

export const soloCategories = [
  { id: 'love', label: '恋愛のこと' },
  { id: 'work', label: '仕事のこと' },
  { id: 'school', label: '学校・部活のこと' },
  { id: 'friends', label: '友だち・人間関係のこと' },
  { id: 'self', label: '自分のこと' },
];

const solo = (deck) => ({ audience: 'solo', questionOrder: 'fixed', adultOnly: false, ...deck, questions: makeQuestions(deck.id, deck.questions) });

